Coord3D *Team::rva0039DA2A(Coord3D *center) const
{
	// The average position of the members that are neither dead nor destroyed.
	Coord3D sum(0.0f, 0.0f, 0.0f);
	Int count = 0;
	for (DLINK_ITERATOR<Object> iter = iterate_TeamMemberList(); !iter.done(); iter.advance())
	{
		if (iter.cur()->isEffectivelyDead())
			continue;
		if (iter.cur()->m_status.test(OBJECT_STATUS_DESTROYED))
			continue;
		const Coord3D *pos = iter.cur()->getPosition();
		sum.x += pos->x;
		sum.y += pos->y;
		sum.z += pos->z;
		++count;
	}

	Real rx, ry, rz;
	if (count > 0)
	{
		Real scale = 1.0f / (Real)count;
		rx = scale * sum.x;
		ry = scale * sum.y;
		rz = scale * sum.z;
	}
	else
	{
		rx = sum.x;
		rz = sum.z;
		ry = sum.y;
	}
	center->x = rx;
	center->y = ry;
	center->z = rz;
	return center;
}

