// FUNCTION: BFME2 0x0039DD4B size=119 name=?rva0039DD4B@Team@@QAE_N_N@Z evidence=?:placeholder tier=A
bool Team::rva0039DD4B(bool ignoreIncomplete)
{
	for (DLINK_ITERATOR<Object> iter = iterate_TeamMemberList(); !iter.done(); iter.advance())
	{
		Object *obj = iter.cur();
		if (obj->isEffectivelyDead())
			continue;

		if (obj->m_status.test(OBJECT_STATUS_DESTROYED))
			continue;

		const ThingTemplate *tmpl = obj->getTemplate();
		if (tmpl->isKindOf(KINDOF_MINE))
			continue;

		if (ignoreIncomplete)
		{
			if (!tmpl->isKindOf(KINDOF_STRUCTURE))
				continue;
			if (obj->m_modelConditions.testBool(67) || obj->m_modelConditions.testBool(68))
				continue;
		}

		if (tmpl->isKindOf(KINDOF_STRUCTURE))
			return true;
	}
	return false;
}

// FUNCTION: BFME2 0x0039DDC2 size=132 name=?rva0039DDC2@Team@@QAE_NVBfmeFixedStorage0004543D@@_N@Z evidence=?:placeholder tier=A
bool Team::hasAnyBuildings(KindOfMaskType kindOf, Bool ignoreIncomplete)
{
	for (DLINK_ITERATOR<Object> iter = iterate_TeamMemberList(); !iter.done(); iter.advance())
	{
		Object *obj = iter.cur();
		if (obj->isEffectivelyDead())
			continue;

		if (obj->m_status.test(OBJECT_STATUS_DESTROYED))
			continue;

		const ThingTemplate *tmpl = obj->getTemplate();
		if (tmpl->isKindOf(KINDOF_MINE))
			continue;

		// A building that is still going up or coming down does not count when asked.
		if (ignoreIncomplete && tmpl->isKindOf(KINDOF_STRUCTURE))
		{
			if (obj->m_modelConditions.testBool(67) || obj->m_modelConditions.testBool(68))
				continue;
		}

		kindOf.set(KINDOF_STRUCTURE);
		if (obj->isKindOfMulti(kindOf, KINDOFMASK_NONE))
			return true;
	}
	return false;
}

