// FUNCTION: BFME2 0x0039DEC4 size=88 name=?hasAnyUnits@Team@@QAE_NXZ evidence=N:ledger tier=A
bool Team::hasAnyUnits()
{
	// Any living, undestroyed member that is not a structure, a projectile or
	// something victory ignores counts as a unit.
	DLINK_ITERATOR<Object> members = iterate_TeamMemberList();
	for (; !members.done(); members.advance())
	{
		Object *member = members.cur();
		if (member->isEffectivelyDead() || member->m_status.test(OBJECT_STATUS_DESTROYED))
			continue;
		const ThingTemplate *kind = member->getTemplate();
		if (kind->isKindOf(KINDOF_STRUCTURE) || kind->isKindOf(KINDOF_PROJECTILE) || kind->isKindOf(KINDOF_IGNORE_FOR_VICTORY))
			continue;
		return true;
	}
	return false;
}

// FUNCTION: BFME2 0x0039DF1C size=107 name=?hasAnyBuildings@Team@@QAE_NVBfmeFixedStorage0004543D@@0@Z evidence=N:ledger tier=A
bool Team::hasAnyBuildings(KindOfMaskType setMask, KindOfMaskType clearMask)
{
	for (DLINK_ITERATOR<Object> iter = iterate_TeamMemberList(); !iter.done(); iter.advance())
	{
		Object *obj = iter.cur();
		if (obj->isEffectivelyDead())
			continue;

		if (obj->m_status.test(OBJECT_STATUS_DESTROYED))
			continue;

		const ThingTemplate *tmpl = obj->getTemplate();
		if (tmpl->isKindOf(KINDOF_STRUCTURE) || tmpl->isKindOf(KINDOF_PROJECTILE) || tmpl->isKindOf(KINDOF_IGNORE_FOR_VICTORY))
			continue;

		if (obj->isKindOfMulti(setMask, clearMask))
			return true;
	}
	return false;
}

// FUNCTION: BFME2 0x0039DF87 size=113 name=?rva0039DF87@Team@@QAE_NPAVBfmeTab1026@@@Z evidence=?:placeholder tier=A
bool Team::hasAnyUnits(ObjectFilter *filter)
{
	Player *player = getControllingPlayer();
	for (DLINK_ITERATOR<Object> iter = iterate_TeamMemberList(); !iter.done(); iter.advance())
	{
		Object *obj = iter.cur();
		if (obj->isEffectivelyDead())
			continue;

		if (obj->m_status.test(OBJECT_STATUS_DESTROYED))
			continue;

		// A structure is not a unit, nor are projectiles or things that do not count for victory.
		const ThingTemplate *tmpl = obj->getTemplate();
		if (tmpl->isKindOf(KINDOF_STRUCTURE) || tmpl->isKindOf(KINDOF_PROJECTILE) || tmpl->isKindOf(KINDOF_IGNORE_FOR_VICTORY))
			continue;

		if (filter->accepts(obj, player))
			return true;
	}
	return false;
}

// FUNCTION: BFME2 0x0039DFF8 size=74 name=?isIdle@Team@@QBE_NXZ evidence=N:ledger tier=A
bool Team::isIdle() const
{
	// Idle unless some living member with an AI is busy.
	Bool allIdle = true;
	DLINK_ITERATOR<Object> members = iterate_TeamMemberList();
	for (; !members.done(); members.advance())
	{
		Object *member = members.cur();
		AIUpdateInterface *brain = member->getAI();
		if (brain != NULL && !member->isEffectivelyDead() && !brain->isIdle())
		{
			allIdle = false;
			break;
		}
	}
	return allIdle;
}

// FUNCTION: BFME2 0x0039E042 size=142 name=?hasAnyObjects@Team@@QAE_N_N@Z evidence=N:ledger tier=A
bool Team::hasAnyObjects(bool flag)
{
	for (DLINK_ITERATOR<Object> iter = iterate_TeamMemberList(); !iter.done(); iter.advance())
	{
		Object *member = iter.cur();
		if (member->isEffectivelyDead())
			continue;

		if (member->m_status.test(OBJECT_STATUS_DESTROYED))
			continue;

		// Structures that are still being raised or sold do not count (the two model conditions have no names here: bits 67 and 68).
		if (flag && member->getTemplate()->isKindOf(KINDOF_STRUCTURE)) {
			if (member->getModelConditionFlags().testShifted((ModelConditionFlagType)67) || member->getModelConditionFlags().testShifted((ModelConditionFlagType)68))
				continue;
		}

		const ThingTemplate *kind = member->getTemplate();
		if (kind->isKindOf(KINDOF_PROJECTILE) || kind->isKindOf(KINDOF_INERT) || kind->isKindOf(KINDOF_IGNORE_FOR_VICTORY))
			continue;

		return true;
	}
	return false;
}

