TeamPrototype *TeamFactory::findTeamPrototypeByID(UnsignedInt wanted)
{
	TeamPrototypeMap::iterator entry = m_prototypes.begin();
	for (; entry != m_prototypes.end(); ++entry)
	{
		TeamPrototype *candidate = entry->second;
		if (candidate->getID() == wanted)
			return candidate;
	}
	return NULL;
}

// FUNCTION: BFME2 0x0039F761 size=68 name=?findTeamByID@TeamFactory@@QAEPAVTeam@@I@Z evidence=N:ledger tier=A
Team *TeamFactory::findTeamByID(UnsignedInt wanted)
{
	// ID 0 is never assigned.
	if (wanted == 0)
		return NULL;
	TeamPrototypeMap::iterator entry = m_prototypes.begin();
	for (; entry != m_prototypes.end(); ++entry)
	{
		Team *found = entry->second->findTeamByID(wanted);
		if (found)
			return found;
	}
	return NULL;
}

// FUNCTION: BFME2 0x0039F7A5 size=127 name=?loadPostProcess@TeamFactory@@MAEXXZ evidence=N:ledger tier=A
void TeamFactory::loadPostProcess()
{
	// The next free IDs are one past the largest ones the loaded prototypes and teams use.
	m_uniqueTeamID = 0;
	m_uniqueTeamPrototypeID = 0;
	for (TeamPrototypeMap::iterator it = m_prototypes.begin(); it != m_prototypes.end(); ++it)
	{
		TeamPrototype *proto = (*it).second;
		if (proto->getID() >= m_uniqueTeamPrototypeID)
			m_uniqueTeamPrototypeID = proto->getID() + 1;
		for (DLINK_ITERATOR<Team> iter = proto->iterate_TeamInstanceList(); !iter.done(); iter.advance())
		{
			UnsignedInt id = iter.cur()->getID();
			if (id >= m_uniqueTeamID)
				m_uniqueTeamID = id + 1;
		}
	}
}

